import{_ as n,a,c as e,b as l}from"./chunks/framework.b9WMfGr4.js";const b=JSON.parse('{"title":"01-文章结构与生命周期","description":"规范技术博客的正文组织框架、生命周期演进流、草稿隔离机制与发布验收准则。","frontmatter":{"title":"01-文章结构与生命周期","date":"2026-10-01T00:00:00.000Z","author":"道林学长","description":"规范技术博客的正文组织框架、生命周期演进流、草稿隔离机制与发布验收准则。","tags":["写作规范","写作流程"]},"headers":[],"relativePath":"posts/0-博客指南/博客的写作规范/01-文章结构与生命周期.md","filePath":"posts/0-博客指南/博客的写作规范/01-文章结构与生命周期.md"}'),p={name:"posts/0-博客指南/博客的写作规范/01-文章结构与生命周期.md"};function i(t,s,o,r,c,d){return a(),e("div",null,[...s[0]||(s[0]=[l(`<h1 class="hidden-duplicate-h1" style="display:none !important;" id="_01-文章结构与生命周期" tabindex="-1">01-文章结构与生命周期 <a class="header-anchor" href="#_01-文章结构与生命周期" aria-label="Permalink to &quot;01-文章结构与生命周期&quot;">​</a></h1><div class="post-cover-wrapper"><img src="https://images.unsplash.com/photo-1455390582262-044cdead277a?auto=format&amp;fit=crop&amp;w=1200&amp;q=80" alt="cover" class="post-cover-image" referrerpolicy="no-referrer" loading="lazy"></div><p>技术博文不仅是代码片段的罗列，更是一份具备独立完整生命周期的工程报告。规范的文章结构与严谨的生命周期管理，能够大幅提升技术沉淀的复用率与传播深度。</p><h2 id="_1-推荐正文组织框架" tabindex="-1">1. 推荐正文组织框架 <a class="header-anchor" href="#_1-推荐正文组织框架" aria-label="Permalink to &quot;1. 推荐正文组织框架&quot;">​</a></h2><p>优秀的博文应当具备清晰的阅读主线与递进逻辑。我们推荐采用问题驱动的经典四段式框架：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang">Text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>1. 问题背景与痛点引入 (Why)</span></span>
<span class="line"><span>     └── 明确业务场景、现实矛盾与直接报错表现</span></span>
<span class="line"><span>2. 核心机理与架构推演 (What)</span></span>
<span class="line"><span>     └── 借助时序图、流程图或源码剖析深层根因</span></span>
<span class="line"><span>3. 实战方案与代码复现 (How)</span></span>
<span class="line"><span>     └── 给出经本地验证的可运行代码与关键参数</span></span>
<span class="line"><span>4. 总结复盘与延伸思考 (Summary &amp; Next)</span></span>
<span class="line"><span>     └── 梳理避坑要点、性能取舍与后续演进建议</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><ul><li><strong>引言突出问题痛点</strong>：在正文开篇，开门见山指出文章所要攻克的核心技术难题、实际业务背景或系统报错特征，切忌冗长寒暄。</li><li><strong>流程图辅助机制阐述</strong>：在深入细节前，优先借助 Mermaid 流程图或架构图直观呈现模块调用链路，降低读者的理解门槛。</li><li><strong>代码块突出关键上下文</strong>：展示代码时，务必注明语言类型与文件标题，重点逻辑辅以行号联动与必要的行高亮，保持代码纯净规范。</li><li><strong>收尾形成经验闭环</strong>：在文末总结本方案的核心权衡与边界条件，指出可能存在的性能副作用与后续优化方向。</li></ul><h2 id="_2-文章生命周期与目录流转" tabindex="-1">2. 文章生命周期与目录流转 <a class="header-anchor" href="#_2-文章生命周期与目录流转" aria-label="Permalink to &quot;2. 文章生命周期与目录流转&quot;">​</a></h2><p>一篇博文从构思到正式发布，经历三个标准化阶段：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang">Text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>未成形碎片 / 临时记录</span></span>
<span class="line"><span>  └── 存放于 drafts/ 目录 (全站排除构建，纯私密草稿)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼  完成初步撰写与排版</span></span>
<span class="line"><span>待审阅测试 / 内部验证</span></span>
<span class="line"><span>  └── 移入 posts/ 对应分类，标注 draft: true 或 private: true</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼  本地 build 验证无误，去除草稿标记</span></span>
<span class="line"><span>正式公开发布</span></span>
<span class="line"><span>  └── git push 提交推流，Actions 自动编译部署</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><ul><li><strong>草稿隔离机制</strong>：根目录下的 <code>drafts/</code> 目录已被全站静态构建引擎与数据加载器直接排除。任何未成形的思路、会议纪要与零散卡片均在此存放，绝不会泄漏或影响生产编译。</li><li><strong>私密与草稿过滤属性</strong>：对于已归入 <code>posts/</code> 目录但仍在修改中的文章，可在 Frontmatter 中设置 <code>draft: true</code> 或 <code>private: true</code>。数据加载器将自动忽略该文件，使其不出现在博文归档、最新文章与侧边栏目录中。</li></ul><h2 id="_3-发布前验证检查清单" tabindex="-1">3. 发布前验证检查清单 <a class="header-anchor" href="#_3-发布前验证检查清单" aria-label="Permalink to &quot;3. 发布前验证检查清单&quot;">​</a></h2><p>向远程公开仓库推送提交前，创作者应依序确认以下自检事项：</p><ol><li><strong>标题唯一性检查</strong>：一级标题在正文首部声明且仅声明一次，其文本与文件名保持同义。</li><li><strong>无中文括号夹注</strong>：通篇检查正文，确保无中文全角括号作补充说明，修饰内容自然融入正文。</li><li><strong>资源引用完备性</strong>：本地专属图片已移入同级 <code>assets/</code> 目录，外链图片已配置防盗链免 Referer 属性。</li><li><strong>本地生产打包验证</strong>：在终端执行 <code>npm run build</code>，必须保证终端无报错输出、无坏链告警且静态页面全部构建成功。</li></ol>`,14)])])}const h=n(p,[["render",i]]);export{b as __pageData,h as default};
